"""Publish separate actual transfer proof without claiming game-path adoption."""
import json,hashlib,shutil
from pathlib import Path
from datetime import datetime,timezone
ROOT=Path(__file__).resolve().parents[1]
read=lambda p:json.loads(p.read_text())
save=lambda p,v:p.write_text(json.dumps(v,indent=2)+'\n')
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
def main():
    cp=read(ROOT/'verification/startup-loading-movie-world-checkpoint.json');CPU=read(ROOT/'verification/bios-transport-CPU-checks.json');GPU=read(ROOT/'verification/GPU-CD-ISR-checks.json');linked=read(ROOT/'verification/CD-stream-linked-checks.json')
    assert cp['CDROM_timing_extension_compared']and CPU['source_instruction_coverage']==[78,78]and GPU['source_instruction_coverage']==[94,94]and linked['cases']==4 and linked['payload_counts']==[64,4096,32768,129118]
    for p in [CPU,GPU,linked]:assert read(Path(p['directory'])/'status.json')['status']=='terminal_pass'
    raw=Path(linked['directory']);cases=read(raw/'cases.json');assert cases[-1]['matched_existing_startup_asset_sha256']=='1dab5d4bf0f90279b8a6712815bca54aeeec797c8cecbf531771f41556063a67'
    for i in range(4):
        assert read(raw/f'case-{i}-native.json')==read(raw/f'case-{i}-C.json')and (raw/f'case-{i}-native-RAM.bin').read_bytes()==(raw/f'case-{i}-C-RAM.bin').read_bytes()
        assert (raw/f'case-{i}-native-payload.bin').read_bytes()==(raw/f'case-{i}-C-payload.bin').read_bytes()
    for name,digest in linked['source_sha256'].items():assert sha(ROOT/'projects/black-ice-white-noise/restoration'/name)==digest
    now=datetime.now(timezone.utc);out=ROOT/'verification/CD-transport-source-review'/now.strftime('%Y%m%dT%H%M%S.%fZ');out.mkdir(parents=True)
    startup=read(Path(cp['original_reference_directory'])/'case-0-C.json')['summary']['asset_disc_requests'];padding=min(0x40000-(((x['bytes']+4+31)//32)*32)for x in startup)
    boundaries=[dict(requested=x['count'],reported_last_word_offset=x['CPU']['registers'][8]-0x1c0000,source_write_span=x['CPU']['registers'][8]+4-0x1c0000,extra_bytes=x['CPU']['registers'][8]+4-0x1c0000-x['count'])for x in cases]
    summary=dict(recorded_at=now.isoformat(),status='actual_CD_CPU_GPU_stream_separately_verified_not_game_integrated',CPU_cases=48,CPU_instructions=[78,78],GPU_cases=64,GPU_instructions=[94,94],linked_cases=4,payload_counts=[64,4096,32768,129118],first_game_startup_asset_matched_bytes=129118,first_game_startup_asset_sha256=cases[-1]['matched_existing_startup_asset_sha256'],file_payload_memcpy_or_scripted_progress=False,C_original_CPU_GPU_execution=False,main_game_CD_transport_file_backed=True,actual_transport_linked_into_game=False,CDROM_baseline_and9byte_timing_extension_compared=True,boundary_observations=boundaries,observed18_asset_requests_minimum_reserved_window_padding_bytes=padding,buffer_padding_verified_for_all_game_calls=False,initial_and_scheduling_providers=['Hostloaded BIOS/GPU code and zero-mainRAM plus declared CPU/GPU/device seed, host CPU API/private return frames andSR2700.','One externally supplied controller tick per loop; shared pinned CDI global672-byte normalization plus FIFO two-byte phase and IRQ device model.','Owned C logical GPU mirrored to shared MMIO shadow; supplied pipeline tail.'],limitations=['Separate API linkage only; current scheduledstartup/loading/movie/world still uses file-backed disc adapters.','Unpatched baseline ISR only; patched/encrypted variants,real game caller/VBI progress integration,global timing/firmware boot/full game not verified.','Source32bytechunks can write beyond requested end; recorded18asset sizes have spare scratch window, but general caller padding/limits not verified.'],implementation_authorship='Coordinator authored CPU/GPU translations, source/API linkage and validation; no new local-model code authorship or weight training.',CPU_report=CPU['directory'],GPU_report=GPU['directory'],linked_report=linked['directory'],audit=str(out))
    save(ROOT/'verification/CD-transport-components-checkpoint.json',summary)
    cp['main_game_CD_transport_file_backed']=True;cp['actual_CD_transport_linked_into_game']=False;cp['CD_transport_components']=summary
    cp['checked_answer']=cp['checked_answer'].replace('GPU CDISR execution,','GPU CDISR execution in this connected game chain,')
    cp['checked_answer']+=' Separate CPU transport48cases/all78instructions and GPU CD IRQ1 handler64cases/all94instructions are now verified. Four actual303C->BUTCH/FIFO->GPU IRQ1->304E/3042 API transfers (64/4096/32768/129118bytes) match original/C complete logical states/RAM/events, including one129118byte startup asset hash. No payload memcpy or scripted progress is used there. This separate API proof has not replaced the file-backed transport in the connected game chain. CDROM baseline and its9byte FIFO timing/interrupt-edge extension are now compared in fresh component and main-chain runs; earlier saved comparisons omitted the extension.'
    save(ROOT/'verification/startup-loading-movie-world-checkpoint.json',cp);session=Path(read(ROOT/'projects/black-ice-white-noise/analysis/current-session.json')['directory']);p=session/'emulator-runtime/summary.json';s=read(p);s['startup_loading_movie_world_checkpoint']=cp;s['CD_transport_components']=summary;save(p,s)
    files=[Path(__file__),ROOT/'scripts/generate_biwn_bios_transport_cpu.py',ROOT/'scripts/check_biwn_bios_transport_cpu.py',ROOT/'scripts/generate_biwn_GPU_CD_ISR.py',ROOT/'scripts/check_biwn_GPU_CD_ISR.py',ROOT/'scripts/probe_biwn_native_CD_stream.py',ROOT/'scripts/check_biwn_CD_stream_linked.py',ROOT/'scripts/check_biwn_bios_mode_cpu.py',ROOT/'scripts/biwn_bios_mode_runtime.py',ROOT/'verification/bios-transport-CPU-checks.json',ROOT/'verification/GPU-CD-ISR-checks.json',ROOT/'verification/CD-stream-linked-checks.json',ROOT/'verification/CD-transport-components-checkpoint.json',ROOT/'verification/startup-loading-movie-world-checkpoint.json',session/'bios-transport-fullCPU-generation.json',session/'GPU-CD-ISR-C-generation.json']
    for name in linked['source_sha256']:files.extend([ROOT/'projects/black-ice-white-noise/restoration'/name,ROOT/'projects/black-ice-white-noise/restoration'/name.replace('.c','.h')])
    files.extend(raw.glob('case-*'));files.extend(raw/n for n in ['report.json','status.json','cases.json','compiler.txt','libCD-stream.dylib']);manifest=[]
    for i,p in enumerate(files):
        target=out/f'{i:03d}-{p.name}';shutil.copy2(p,target);assert sha(p)==sha(target);manifest.append(dict(source=str(p),snapshot=str(target),sha256=sha(p)))
    save(out/'manifest.json',manifest);save(out/'checkpoint.json',summary)
    (out/'who-and-prompts.txt').write_text(summary['implementation_authorship']+'\nNo local-model code-generation prompt in these translations/tests. Source machine instructions and device model supplied original comparison. CPU78/GPU94 fixed blocks plus source/API calls linked; no NativeCPU/GPU instructions run on C transfer path. Main game transport not yet adopted.\n')
    p=ROOT/'CURRENT DECOMPILATION.txt';p.write_text('ACTUAL CD TRANSPORT COMPONENTS AND API STREAM\n'+now.isoformat()+'\n\n'+json.dumps(summary,indent=2)+'\n\nEARLIER CHECKPOINTS\n'+p.read_text())
    print(json.dumps(dict(status=summary['status'],audit=str(out),linked_cases=4,boundaries=boundaries,minimum_observed_scratch_padding=padding)))
if __name__=='__main__':main()
